<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verifikasi BPB</title>
<style>body{margin:0;background:#f4f7fb;color:#182230;font-family:Arial,sans-serif}.wrap{max-width:720px;margin:6vh auto;padding:20px}.card{background:#fff;border-radius:14px;box-shadow:0 8px 30px rgba(20,40,80,.1);overflow:hidden}.head{background:#2057a3;color:#fff;padding:24px}.body{padding:24px}.status{display:inline-block;padding:8px 12px;border-radius:20px;font-weight:bold}.valid{background:#dcf6e8;color:#167447}.invalid{background:#fee5e5;color:#a32121}.hash{word-break:break-all;background:#f6f8fa;padding:10px;border-radius:6px;font-family:monospace}.sign{padding:12px 0;border-bottom:1px solid #eee}.muted{color:#667085;font-size:13px}</style></head><body><div class="wrap"><div class="card"><div class="head"><h1>Verifikasi BPB</h1><div>Dokumen elektronik internal SIGAPP</div></div><div class="body">
<?php if (! $bpb): ?><span class="status invalid">Token tidak valid</span><p>Dokumen tidak ditemukan.</p>
<?php else: ?><span class="status <?= $valid ? 'valid' : 'invalid' ?>"><?= $valid ? 'Dokumen terverifikasi' : 'Verifikasi tidak cocok' ?></span><h2><?= esc($bpb['nomor']) ?></h2><p>Status: <strong><?= esc($bpb['status_label']) ?></strong></p><div class="muted">Hash SHA-256</div><div class="hash"><?= esc($bpb['current_document_hash']) ?></div><h3>Penanda tangan</h3><?php foreach ($signatures as $signature): ?><div class="sign"><strong><?= esc(ucwords(str_replace('_', ' ', $signature['role']))) ?> — <?= esc($signature['signer_name']) ?></strong><div class="muted"><?= esc($signature['signed_at']) ?></div></div><?php endforeach; ?><?php endif; ?>
</div></div></div></body></html>
